<?php $labels=['certificate'=>'Apply for a student certificate','mentor'=>'Request a mentor','visit'=>'Request a campus visit','support'=>'Create a support ticket']; ?>
<section class="p-section"><h2><?= e($labels[$type]??'Submit a request') ?></h2>
<form class="p-form" method="post" action="<?= base_url('/partner/requests') ?>"><?= csrf_field() ?><input type="hidden" name="type" value="<?= e($type) ?>">
<?php if($type==='certificate'): ?><label>Student<select name="student_id"><option value="">Select student</option><?php foreach($students as $st): ?><option value="<?= (int)$st['student_user_id'] ?>"><?= e($st['name']) ?></option><?php endforeach ?></select></label><label>Course / completed batch<input name="course_batch"></label><label>Completion date<input type="date" name="completion_date"></label><label>Attendance information<input name="attendance"></label><label>Project completion status<select name="project_status"><option>Complete</option><option>In progress</option><option>Not applicable</option></select></label>
<?php elseif($type==='mentor'): ?><label>Course<input name="course" required></label><label>Expected batch size<input type="number" min="1" name="batch_size"></label><label>Teaching mode<select name="teaching_mode"><option>In person</option><option>Online</option><option>Hybrid</option></select></label><label>Preferred timing<input name="preferred_timing"></label><label>Start date<input type="date" name="start_date"></label><label>Preferred language<input name="language"></label>
<?php elseif($type==='visit'): ?><label>Visit purpose<select name="purpose"><option>Partnership Discussion</option><option>Batch Launch</option><option>Student Counselling</option><option>Trainer Demonstration</option><option>Technical Setup</option><option>Marketing Assistance</option><option>Academic Review</option><option>General Support</option></select></label><label>Preferred date<input type="date" name="preferred_date"></label><label>Preferred time<input type="time" name="preferred_time"></label><label>Urgency<select name="priority"><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></label><label>Contact person<input name="contact_person"></label><label>Institution address<input name="address"></label>
<?php else: ?><label>Category<select name="category"><option>Admissions</option><option>Batches</option><option>Payments</option><option>Trainer Issues</option><option>Certificates</option><option>Website / Technical Issue</option><option>Course Content</option><option>Marketing</option><option>Other</option></select></label><label>Priority<select name="priority"><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option><option value="low">Low</option></select></label><?php endif ?>
<label class="wide">Subject<input name="subject" required maxlength="180"></label><label class="wide">Description<textarea name="details" required rows="4"></textarea></label><div class="wide"><button class="tcm-btn primary">Submit Request</button></div></form></section>
<section class="p-section"><h2>Request history</h2><?php if(!$rows): ?><div class="p-empty">No requests yet.</div><?php else: ?><div class="p-table-wrap"><table class="p-table"><thead><tr><th>Request</th><th>Status</th><th>Priority</th><th>Submitted</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['subject']) ?><br><span class="p-muted"><?= e($r['details']) ?></span><?php if($r['admin_note']): ?><br><span class="p-muted">TCM One: <?= e($r['admin_note']) ?></span><?php endif ?></td><td><span class="p-pill"><?= e(str_replace('_',' ',$r['status'])) ?></span></td><td><?= e($r['priority']) ?></td><td><?= e(date('d M Y',strtotime($r['created_at']))) ?></td><td><?= e(date('d M Y',strtotime($r['updated_at']))) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
